fn rolling_max(s: &Vec<i8>) -> Option<i8> {
    // If there are fewer than two elements, we can't have a "second largest"
    if s.len() < 2 {
        return None;
    }

    // Initialize max and second_max using the first two elements
    let mut max = s[0];
    let mut second = s[1];
    if max < second {
        std::mem::swap(&mut max, &mut second);
    }

    // Scan the rest of the slice, updating max and second as needed
    for &x in &s[2..] {
        if x > max {
            // x becomes the new maximum; old max becomes second
            second = max;
            max = x;
        } else if x > second {
            // x falls between max and current second
            second = x;
        }
    }

    Some(second)
}

